import math
import random

from hypothesis import given, settings
from hypothesis import strategies as st

import pytest

from radiate import SIGMA, equilibrium_temperature, surface_temperature


def test_earth_equilibrium():
    assert equilibrium_temperature(1361.0, 0.306) == pytest.approx(254.6, abs=0.5)


def test_one_layer_surface():
    # Earth-like case with one perfectly absorbing layer.
    t_s = surface_temperature(1361.0, 0.306, 1)
    assert t_s == pytest.approx(302.8, abs=0.5)


def test_zero_layers_reduces_to_teq_exactly():
    for _ in range(100):
        s = random.uniform(10.0, 10000.0)
        a = random.uniform(0.0, 1.0)
        assert surface_temperature(s, a, 0) == equilibrium_temperature(s, a)


def test_mercury():
    assert equilibrium_temperature(9082.0, 0.088) == pytest.approx(439.4, abs=1.0)


@given(
    flux=st.floats(min_value=1.0, max_value=1e5),
    albedo_low=st.floats(min_value=0.0, max_value=0.99),
    delta=st.floats(min_value=0.001, max_value=1.0 - 1e-9),
)
def test_teq_decreases_with_albedo(flux, albedo_low, delta):
    albedo_high = min(albedo_low + delta, 1.0 - 1e-9)
    assert equilibrium_temperature(flux, albedo_high) < equilibrium_temperature(
        flux, albedo_low
    )


@given(
    flux=st.floats(min_value=1.0, max_value=1e5),
    albedo=st.floats(min_value=0.0, max_value=0.99),
)
def test_doubling_distance_scaling(flux, albedo):
    t1 = equilibrium_temperature(flux, albedo)
    t2 = equilibrium_temperature(flux / 4.0, albedo)  # double distance => S/4
    assert t2 == pytest.approx(t1 * 2 ** (-0.5), rel=1e-9)


def test_sigma_constant():
    assert SIGMA == 5.670374419e-8

